def count_threshold_triplets(arr, a, b, c):
 answer=0
 for i in range(len(arr)):
  for j in range(i+1,len(arr)):
   for k in range(j+1,len(arr)):
    answer+=abs(arr[i]-arr[j])<=a and abs(arr[j]-arr[k])<=b and abs(arr[i]-arr[k])<=c
 return answer

